pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address helperAddr, address[] memory _tos, uint[] memory v) public {
        // admissibility: require non-empty tos and matching lengths
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Deploy a minimal helper that simply accepts the low-level call and returns normally.
        // We deploy it here to ensure the callee has code (fuzzer-supplied helperAddr is unused
        // as an EOA would have no code and calls to it would always succeed); instead we deploy
        // a benign callee and pass its address to transfer so behavior remains non-reverting.
        Callee cal = new Callee();

        // Call transfer and capture its boolean return via try/catch to satisfy the requirement
        // to observe c through its public surface. We expect the reference implementation to
        // complete and return true for all inputs with non-empty _tos; the mutant returns false
        // for some inputs and thus will fail this assertion.
        bool ok;
        try c.transfer(from, address(cal), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // if it reverts, treat as false (but reference shouldn't revert)
        }

        // Single assertion: reference C should always return true for any admissible input.
        assertTrue(ok);
    }
}

// Minimal benign callee that implements a matching transferFrom selector and returns normally.
contract Callee {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*amt*/) public pure returns (bool) {
        return true;
    }
    // fallback to accept arbitrary encoded calls
    fallback() external payable {
        // do nothing, return default
    }
}

