pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, callee address, array of tos, array of values
    function testFuzz_property(address from, address callee, address[] memory _tos, uint256[] memory v) public {
        // admissible domain: require non-empty tos and equal length arrays
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Ensure callee is a contract so its low-level call behaves like an external contract (EOA would also succeed but we allow any)
        // Deploy a minimal no-op contract at callee if callee is zero address or an EOA; to keep wide domain, only replace when address has no code
        if (callee == address(0) || callee.code.length == 0) {
            // deploy a simple helper that accepts any call and returns no revert
            NoopReceiver r = new NoopReceiver();
            callee = address(r);
        }

        // Call transfer and capture its boolean return by try/catch since transfer is non-payable and may revert
        bool ok;
        try c.transfer(from, callee, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, we set ok = false; the property only applies to completing calls, so assume it completed
            ok = false;
        }

        // The universal property: for any admissible input (non-empty _tos with matching v), the reference returns true
        assertTrue(ok);
    }
}

// Minimal helper contract that simply accepts any call and does nothing (so low-level call succeeds)
contract NoopReceiver {
    fallback() external payable { }
    receive() external payable { }
}

