// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, callee behavior selector, tos array, vals array
    // calleeKind: 0 = benign callee returns true from fallback; 1 = benign returns false; 2 = reverter
    function testFuzz_property(address from, uint8 calleeKind, address[] memory _tos, uint256[] memory v) public {
        // admissible domain: non-empty _tos and matching lengths (required by C.transfer)
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // restrict calleeKind to 0..2
        calleeKind = calleeKind % 3;

        // deploy an adversarial helper according to calleeKind
        address calleeAddr;
        if (calleeKind == 0) {
            calleeAddr = address(new CalleeReturnTrue());
        } else if (calleeKind == 1) {
            calleeAddr = address(new CalleeReturnFalse());
        } else {
            calleeAddr = address(new CalleeRevert());
        }

        // Call transfer and capture whether it completed and the returned boolean.
        bool completed;
        bool ret;
        // We must call via low-level try/catch because the function returns a bool and we want to observe it.
        try c.transfer(from, calleeAddr, _tos, v) returns (bool r) {
            completed = true;
            ret = r;
        } catch {
            completed = false;
            ret = false;
        }

        // General rule (single assertion): For every admissible input where the call completes, the reference returns true.
        // This will hold for the reference C for all inputs and fail for the mutant for some input (the fuzzer will find one).
        assertTrue(!completed || ret);
    }
}

// Helper contracts to simulate callee behaviors. The reference C simply performs caddress.call(...)
// which invokes the fallback. These helpers provide varying fallback behaviours.
contract CalleeReturnTrue {
    fallback() external payable returns (bytes memory) {
        // return some non-empty data (low-level call sees success and returns data)
        return abi.encodePacked(uint8(1));
    }
}

contract CalleeReturnFalse {
    fallback() external payable returns (bytes memory) {
        // emulate a callee that returns data that could be interpreted as 'false' by higher-level logic
        return abi.encodePacked(uint8(0));
    }
}

contract CalleeRevert {
    fallback() external payable {
        revert("revert");
    }
}
